/* Malta Driving Master 45.8.31.49.1 — exact Home renderer mount for quick account entry
   Targets the real .hm30/.hm30-top markup generated by views.home().
   No MutationObserver. No polling. No enforcement changes. */
(function(){
  'use strict';
  if(window.MDM_ACCOUNT_HOME_MOUNT_FIX)return;

  function place(){
    try{
      const bridge=window.MDM_ACCOUNT_ENTRY_BRIDGE;
      if(!bridge)return false;

      const home=document.querySelector('.hm30');
      const top=home&&home.querySelector('.hm30-top');
      if(!home||!top)return false;

      let entry=document.getElementById('mdmQuickAccountEntry');
      if(!entry){
        if(typeof bridge.mount==='function')bridge.mount();
        entry=document.getElementById('mdmQuickAccountEntry');
      }
      if(!entry)return false;

      entry.style.cssText='display:flex;gap:8px;flex-wrap:wrap;margin:12px 0 14px;position:relative;right:auto;top:auto;z-index:auto;justify-content:flex-start;width:100%';

      if(entry.parentElement!==home || top.nextElementSibling!==entry){
        home.insertBefore(entry,top.nextSibling);
      }
      return true;
    }catch(_){return false;}
  }

  function schedule(){
    setTimeout(place,30);
    setTimeout(place,120);
  }

  document.addEventListener('click',schedule,false);
  window.addEventListener('pageshow',schedule);
  window.addEventListener('load',schedule,{once:true});
  document.addEventListener('visibilitychange',function(){if(!document.hidden)schedule();});

  window.MDM_ACCOUNT_HOME_MOUNT_FIX=Object.freeze({version:'45.8.31.49.1',place,schedule});
  schedule();
})();
